package utils

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

// ==================== NEW CODE (GENERATED BY AI) ====================
func TestParseSGRMouse_Comprehensive(t *testing.T) {
	tests := []struct {
		name       string
		input      []byte
		wantValid  bool
		wantBtn    MouseBtn
		wantAction MouseAction
		wantX      int
		wantY      int
	}{
		// --- POSITIVE SCENARIOS ---
		{
			name:       "Positive: Left click press at 10,20 converts to 9,19",
			input:      []byte("\x1b[<0;10;20M"),
			wantValid:  true,
			wantBtn:    MouseBtnLeft,
			wantAction: MouseActionPress,
			wantX:      9,
			wantY:      19,
		},
		{
			name:       "Positive: Left click release at 10,20 converts to 9,19",
			input:      []byte("\x1b[<0;10;20m"),
			wantValid:  true,
			wantBtn:    MouseBtnLeft,
			wantAction: MouseActionRelease,
			wantX:      9,
			wantY:      19,
		},
		{
			name:       "Positive: Mouse drag/move with left button pressed",
			input:      []byte("\x1b[<32;15;25M"),
			wantValid:  true,
			wantBtn:    MouseBtnLeft,
			wantAction: MouseActionMove,
			wantX:      14,
			wantY:      24,
		},
		{
			name:       "Positive: Mouse wheel scroll up",
			input:      []byte("\x1b[<64;5;5M"),
			wantValid:  true,
			wantBtn:    MouseBtnWheelUp,
			wantAction: MouseActionPress,
			wantX:      4,
			wantY:      4,
		},
		{
			name:       "Positive: Mouse wheel scroll down",
			input:      []byte("\x1b[<65;5;5M"),
			wantValid:  true,
			wantBtn:    MouseBtnWheelDown,
			wantAction: MouseActionPress,
			wantX:      4,
			wantY:      4,
		},

		// --- NEGATIVE & EDGE CASES ---
		{
			name:      "Edge case: Empty byte slice input",
			input:     []byte{},
			wantValid: false,
		},
		{
			name:      "Negative: Invalid ANSI SGR sequence prefix",
			input:     []byte("\x1b[A12345M"),
			wantValid: false,
		},
		{
			name:      "Negative: Missing trailing M/m action character",
			input:     []byte("\x1b[<0;10;20"),
			wantValid: false,
		},
		{
			name:      "Negative: Incomplete coordinates (missing Y axis)",
			input:     []byte("\x1b[<0;10M"),
			wantValid: false,
		},
		{
			name:      "Negative: Non-numeric characters inside coordinates",
			input:     []byte("\x1b[<0;abc;20M"),
			wantValid: false,
		},
		{
			name:       "Edge case: Zero coordinates handled safely without integer underflow",
			input:      []byte("\x1b[<0;0;0M"),
			wantValid:  true,
			wantBtn:    MouseBtnLeft,
			wantAction: MouseActionPress,
			wantX:      0,
			wantY:      0,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			res, ok := ParseSGRMouse(tt.input)
			if !tt.wantValid {
				assert.False(t, ok)
				assert.Nil(t, res)
			} else {
				assert.True(t, ok)
				assert.NotNil(t, res)
				assert.Equal(t, tt.wantBtn, res.Button)
				assert.Equal(t, tt.wantAction, res.Action)
				assert.Equal(t, tt.wantX, res.X)
				assert.Equal(t, tt.wantY, res.Y)
			}
		})
	}
}
// ==================== END OF NEW CODE ====================
